use strict;
use warnings;
use File::Find;

my @decls;
my %pkg_of_file;

sub process_file {
  my $path = $_;
  return unless $path =~ /\.go$/;
  return if $path =~ /_test\.go$/;
  return unless $path =~ m{/internal/};
  open my $fh, "<", $path or die $!;
  my $pkg;
  my $in_block_comment = 0;
  my $lineno = 0;
  while (my $line = <$fh>) {
    $lineno++;
    if ($in_block_comment) {
      if ($line =~ m{\*/}) { $in_block_comment = 0; }
      next;
    }
    if ($line =~ m{/\*} && $line !~ m{\*/}) { $in_block_comment = 1; next; }
    next if $line =~ /^\s*\/\//;
    if ($line =~ /^package\s+(\w+)/) { $pkg = $1; $pkg_of_file{$path} = $pkg; }
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      push @decls, { name => $name, recv => $recv // "", pkg => $pkg // "", path => $path, line => $lineno };
    }
  }
  close $fh;
}

find({ wanted => sub { process_file() if -f }, no_chdir => 1 }, "/bench/repo/internal");

print "Total decls: " . scalar(@decls) . "\n";
foreach my $d (sort { $a->{name} cmp $b->{name} } @decls) {
  my $r = $d->{recv} ? "($d->{recv}) " : "";
  my $rel = $d->{path}; $rel =~ s{^/bench/repo/}{};
  print "$d->{pkg} $r$d->{name} — $rel:$d->{line}\n";
}
'

