perl -e '
use strict;
use warnings;

# Load declarations
open my $lf, "<", "/tmp/internal_go.txt" or die $!;
my @files = <$lf>;
chomp @files;
close $lf;

my @decls;
foreach my $path (@files) {
  open my $fh, "<", $path or die $!;
  my $pkg;
  my $lineno = 0;
  while (my $line = <$fh>) {
    $lineno++;
    next if $line =~ /^\s*\/\//;
    if ($line =~ /^package\s+(\w+)/) { $pkg = $1; }
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      next if $name eq "init";
      my $rel = $path; $rel =~ s{^/bench/repo/}{};
      push @decls, { name => $name, recv => $recv // "", pkg => $pkg // "", path => $rel, line => $lineno, is_method => defined($recv) && $recv ne "" };
    }
  }
  close $fh;
}

# Load all go file contents
open my $af, "<", "/tmp/all_go.txt" or die $!;
my @allfiles = <$af>;
chomp @allfiles;
close $af;

my %file_pkg;
my %file_lines;
foreach my $path (@allfiles) {
  open my $fh, "<", $path or die "$path: $!";
  my @lines = <$fh>;
  close $fh;
  $file_lines{$path} = \@lines;
  for my $line (@lines) {
    if ($line =~ /^package\s+(\w+)/) { $file_pkg{$path} = $1; last; }
  }
}

# For each declaration, count call sites
# Strategy:
# - package-level func: count pkg.Name(  OR  Name( in same package (but not declaration)
# - method: count .Name(  excluding declaration line
# Also count unique calling files

my @results;
foreach my $d (@decls) {
  my $name = $d->{name};
  my $pkg = $d->{pkg};
  my $decl_path = "/bench/repo/" . $d->{path};
  my $decl_line = $d->{line};
  my $sites = 0;
  my %callers; # unique files
  my %caller_funcs; # approximate unique calling functions

  foreach my $path (@allfiles) {
    my $lines = $file_lines{$path};
    my $fpkg = $file_pkg{$path} // "";
    my $current_func = "";
    for (my $i = 0; $i < @$lines; $i++) {
      my $line = $lines->[$i];
      my $ln = $i + 1;
      if ($line =~ /^func\s+(?:\([^)]+\)\s+)?(\w+)\s*\(/) {
        $current_func = $1;
      }
      # skip declaration itself
      if ($path eq $decl_path && $ln == $decl_line) { next; }
      next if $line =~ /^\s*\/\//;

      my $matched = 0;
      if ($d->{is_method}) {
        # .Name( or .Name[ for generics - but mainly .Name(
        if ($line =~ /\.$name\s*\(/) { $matched = 1; }
      } else {
        # qualified: pkg.Name(
        if ($line =~ /\b\Q$pkg\E\.\Q$name\E\s*\(/) { $matched = 1; }
        # unqualified in same package
        elsif ($fpkg eq $pkg && $line =~ /(?<![.\w])\Q$name\E\s*\(/) { $matched = 1; }
      }
      if ($matched) {
        $sites++;
        $callers{$path}++;
        $caller_funcs{"$path:$current_func"}++ if $current_func;
      }
    }
  }
  push @results, {
    %$d,
    sites => $sites,
    files => scalar(keys %callers),
    funcs => scalar(keys %caller_funcs),
  };
}

# Sort by sites desc
@results = sort { $b->{sites} <=> $a->{sites} || $b->{files} <=> $a->{files} } @results;

print "TOP 40 by call sites:\n";
printf "%-6s %-6s %-6s %-8s %-40s %s\n", "sites", "files", "funcs", "method", "symbol", "path";
for my $i (0..39) {
  last if $i > $#results;
  my $r = $results[$i];
  my $sym = ($r->{recv} ? "($r->{recv}) " : "") . $r->{name};
  printf "%-6d %-6d %-6d %-8s %-40s %s\n", $r->{sites}, $r->{files}, $r->{funcs}, ($r->{is_method}?"yes":"no"), "$r->{pkg}.$r->{name}", "$r->{path}:$r->{line}";
}
'

