# Breakdown of top candidates: production vs test, exclude declarations
perl -e '
use strict;
use warnings;

my @syms = qw(
  CompileToStatement NewEngine NewSchema GenUUID addArg
  NewService Compile Field DefaultEngine jsonArrayExpr getConstValue
  ConvertStringToInt32 AppendConditions RenderHTML ExtractTags
  ExtractProperties GenerateSnippet RenderMarkdown Register
  ParseCronExpression GetCurrentVersion AllowAnonymous
  WithTagExtension WithMentionExtension DefaultAttachmentEngine
  NewAttachmentSchema GetHTMLMeta Post ValidateURL
  HasPrefixes RandomString ValidateEmail ReplaceString
  qualifyColumn sqlOperator expectLiteral renderCondition
  renderNode renderChildren getIdentName combineAnd combineOr
  likePattern escapeLikeLiteral toFloat toInt64 asFloats
  mapConditions combineConditions buildCondition
  extractTextFromNode uniquePreserveCase truncateAtWord
  GetJobName Logging Recovery Timeout Chain
  IsVersionGreaterThan IsVersionGreaterOrEqualThan
  DetectJPEG ExtractVideo
  GenerateSigningSecret ValidateSigningSecret
  DefaultTranscriptionModel FindProvider
  GetImage GetObject UploadObject
  Send SendAsync Format
  ApplyOptions WithHTTPClient
  WebMOpusToWAV IsWebMContentType
);

open my $af, "<", "/tmp/all_go.txt" or die $!;
my @allfiles = <$af>; chomp @allfiles; close $af;

# also get all unique exported/unexported names from decls and count each
open my $lf, "<", "/tmp/internal_go.txt" or die $!;
my @ifiles = <$lf>; chomp @ifiles; close $lf;
my %decl_count;
my %decl_info;
foreach my $path (@ifiles) {
  open my $fh, "<", $path or die $!;
  while (my $line = <$fh>) {
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
      my ($recv, $name) = ($1 // "", $2);
      next if $name eq "init";
      $decl_count{$name}++;
      my $rel = $path; $rel =~ s{^/bench/repo/}{};
      push @{$decl_info{$name}}, { recv => $recv, path => $rel, pkg => "" };
    }
  }
  close $fh;
}

print "Names declared exactly once (unique symbols):\n";
my @unique = grep { $decl_count{$_} == 1 } keys %decl_count;
print "unique names: " . scalar(@unique) . " / total names: " . scalar(keys %decl_count) . "\n";

# Count call sites for unique names
my @counts;
foreach my $name (@unique) {
  my $total = 0;
  my $prod = 0;
  my $test = 0;
  my $decl = 0;
  my %files;
  foreach my $path (@allfiles) {
    open my $fh, "<", $path or die $!;
    my $ln = 0;
    while (my $line = <$fh>) {
      $ln++;
      next if $line =~ /^\s*\/\//;
      # match Name( as identifier call, or .Name(
      if ($line =~ /(?:^|[^.\w])\Q$name\E\s*\(/ || $line =~ /\.\Q$name\E\s*\(/) {
        if ($line =~ /^func\s+(?:\([^)]+\)\s+)?\Q$name\E\s*\(/) {
          $decl++;
          next;
        }
        $total++;
        my $is_test = ($path =~ /_test\.go$/ || $path =~ /\/test\//) ? 1 : 0;
        if ($is_test) { $test++; } else { $prod++; }
        $files{$path}++;
      }
    }
    close $fh;
  }
  push @counts, { name => $name, total => $total, prod => $prod, test => $test, files => scalar(keys %files), path => $decl_info{$name}[0]{path}, recv => $decl_info{$name}[0]{recv} };
}

@counts = sort { $b->{total} <=> $a->{total} || $b->{prod} <=> $a->{prod} } @counts;
print "\nTOP unique-name symbols by total call sites (excl decl):\n";
printf "%-6s %-6s %-6s %-6s %-45s %s\n", "total", "prod", "test", "files", "symbol", "path";
for my $i (0..50) {
  last if $i > $#counts;
  my $r = $counts[$i];
  next if $r->{total} < 3;
  my $sym = ($r->{recv} ? "($r->{recv}) " : "") . $r->{name};
  printf "%-6d %-6d %-6d %-6d %-45s %s\n", $r->{total}, $r->{prod}, $r->{test}, $r->{files}, $sym, $r->{path};
}
'
